input.content:
@font-face{font-family:"Bebas";src:url("assets/fonts/bebas.woff2") format("woff2");font-display:swap}
@font-face{font-family:"Luckiest";src:url("assets/fonts/luckiest.woff2") format("woff2");font-display:swap}
@font-face{font-family:"Barlow";src:url("assets/fonts/barlow-600.woff2") format("woff2");font-weight:600;font-display:swap}
@font-face{font-family:"Barlow";src:url("assets/fonts/barlow-800.woff2") format("woff2");font-weight:800;font-display:swap}

:root{
  --ink:#071021;
  --navy:#0b1830;
  --navy-2:#10264b;
  --blue:#1d4f8c;
  --gold:#f6b83f;
  --gold-hi:#ffe6a0;
  --gold-deep:#b86b12;
  --cream:#fff3d2;
  --paper:#f2e4c3;
  --red:#ed5a42;
  --teal:#3ad0bd;
  --line:rgba(246,184,63,.33);
  --shadow:0 18px 55px rgba(0,0,0,.45);
}

*{box-sizing:border-box}
html,body{height:100%}
html{background:#071021}
body{
  margin:0;
  overflow:hidden;
  color:var(--cream);
  background:#071021;
  font-family:"Barlow","Arial Narrow",sans-serif;
  -webkit-font-smoothing:antialiased;
  overscroll-behavior:none;
  touch-action:none;
  user-select:none;
  -webkit-user-select:none;
}
button{font:inherit;color:inherit;border:0;background:none;cursor:pointer;-webkit-tap-highlight-color:transparent}
button:focus-visible{outline:2px solid var(--gold-hi);outline-offset:4px}
#scene{position:fixed;inset:0;width:100%;height:100%;display:block;background:#0a1731}

.screen-fx{position:fixed;inset:0;pointer-events:none;z-index:5;overflow:hidden}
.screen-fx .grain{
  position:absolute;inset:-30%;
  opacity:.10;
  background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 220 220' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.75'/%3E%3C/svg%3E");
  animation:grain 1.2s steps(3) infinite;
  mix-blend-mode:soft-light;
}
@keyframes grain{0%{transform:translate(0,0)}25%{transform:translate(-2%,3%)}50%{transform:translate(3%,-2%)}75%{transform:translate(-1%,-3%)}100%{transform:translate(2%,2%)}}
.speed-fx{
  position:absolute;inset:0;
  opacity:0;
  background:
    radial-gradient(ellipse at 50% 58%,transparent 22%,rgba(3,10,22,.10) 48%,rgba(3,10,22,.55) 100%),
    repeating-conic-gradient(from 0deg at 50% 52%,transparent 0deg 8deg,rgba(255,241,204,.12) 8.1deg 8.5deg,transparent 8.8deg 17deg);
  mask:radial-gradient(ellipse at 50% 52%,transparent 26%,#000 58%);
  -webkit-mask:radial-gradient(ellipse at 50% 52%,transparent 26%,#000 58%);
  transition:opacity .5s;
  animation:rush 1.1s linear infinite;
}
@keyframes rush{to{transform:rotate(.8deg) scale(1.02)}}
.vignette{
  position:absolute;inset:0;
  background:
    radial-gradient(ellipse at 50% 48%,transparent 35%,rgba(2,7,16,.38) 78%,rgba(1,5,13,.84) 100%),
    linear-gradient(180deg,rgba(2,7,16,.32),transparent 18%,transparent 72%,rgba(2,7,16,.52));
}
.letterbox{position:absolute;left:0;right:0;height:0;background:var(--ink);transition:height .6s cubic-bezier(.2,.8,.2,1);z-index:2}
.letterbox.top{top:0}
.letterbox.bottom{bottom:0}
body.in-game .letterbox{height:0}

/* ---------------- MENU ---------------- */
.menu{
  position:fixed;inset:0;z-index:10;
  display:flex;flex-direction:column;
  padding:max(26px,env(safe-area-inset-top)) max(42px,calc(env(safe-area-inset-right) + 32px)) max(24px,env(safe-area-inset-bottom)) max(44px,calc(env(safe-area-inset-left) + 34px));
  transition:opacity .5s ease,visibility .5s;
  isolation:isolate;
}
.menu::before{
  content:"";position:absolute;inset:0;z-index:-2;
  background:
    radial-gradient(ellipse at 72% 48%,transparent 0 23%,rgba(7,16,33,.1) 38%,rgba(7,16,33,.72) 71%,rgba(5,12,26,.94) 100%),
    linear-gradient(90deg,rgba(5,12,26,.93) 0%,rgba(5,12,26,.78) 28%,rgba(5,12,26,.22) 58%,rgba(5,12,26,.08) 100%);
}
.menu::after{
  content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;
  background-image:radial-gradient(rgba(255,243,210,.17) .7px,transparent .8px);
  background-size:5px 5px;
  opacity:.20;
  mask:linear-gradient(90deg,#000,transparent 62%);
  -webkit-mask:linear-gradient(90deg,#000,transparent 62%);
}
.menu-shade{
  position:absolute;left:0;top:0;bottom:0;width:49%;z-index:-1;
  background:linear-gradient(90deg,rgba(5,12,26,.28),transparent);
  border-right:1px solid rgba(246,184,63,.06);
  pointer-events:none;
}
.menu.is-hidden{opacity:0;visibility:hidden;pointer-events:none}
.menu.is-hidden .menu-copy,.menu.is-hidden .menu-top,.menu.is-hidden .menu-foot,.menu.is-hidden .wanted-card{transform:translateY(10px)}
.menu-copy,.menu-top,.menu-foot,.wanted-card{transition:transform .55s ease,opacity .45s ease}

.menu-top{display:flex;align-items:flex-start;justify-content:space-between;flex:0 0 auto;position:relative;z-index:2}
.brand{display:flex;align-items:center;gap:11px;color:var(--gold);font-family:"Bebas",sans-serif;font-size:13px;letter-spacing:2.6px;line-height:1.12;text-shadow:0 2px 0 rgba(0,0,0,.55)}
.brand b{color:var(--cream);font-weight:400;letter-spacing:3.6px}
.brand-mark{width:36px;height:36px;filter:drop-shadow(0 3px 0 rgba(0,0,0,.5))}
.case-file{text-align:right;font-family:"Bebas",sans-serif;letter-spacing:2.8px;font-size:12px;color:rgba(255,243,210,.55);line-height:1.3}
.case-file b{color:var(--gold)}
.case-file span{display:block;font-family:"Barlow";font-weight:600;font-size:9px;letter-spacing:2.2px;color:rgba(255,243,210,.42);margin-top:3px}

.menu-copy{
  width:min(610px,52vw);
  margin:auto 0;
  padding:2.5vh 0 1.5vh;
  position:relative;z-index:2;
}
.kicker{
  display:flex;align-items:center;gap:10px;
  font-family:"Bebas",sans-serif;font-size:12px;letter-spacing:4.5px;color:var(--gold);
  margin-bottom:1.5vh;
}
.kicker i{width:24px;height:1px;background:var(--gold);display:block;box-shadow:0 0 10px rgba(246,184,63,.8)}
.logo{
  margin:0;
  display:flex;flex-direction:column;align-items:flex-start;
  font-family:"Luckiest",sans-serif;font-weight:400;line-height:.73;
  letter-spacing:-.012em;
  filter:drop-shadow(0 8px 0 rgba(0,0,0,.23));
  transform:skew(-3deg);
}
.logo-sly,.logo-runs{
  display:block;position:relative;
  -webkit-text-stroke:clamp(2px,.24vw,4px) #0a1425;
  paint-order:stroke fill;
}
.logo-sly{
  font-size:clamp(91px,12.4vw,194px);
  color:var(--cream);
  text-shadow:0 .06em 0 #c9a46a,0 .11em 0 #0a1425,0 .15em 22px rgba(0,0,0,.45);
}
.logo-runs{
  font-size:clamp(92px,12.8vw,201px);
  color:var(--gold);
  margin-left:clamp(34px,4.8vw,72px);
  text-shadow:0 .055em 0 #ffd87b,0 .11em 0 #a3540b,0 .15em 0 #0a1425,0 .19em 24px rgba(0,0,0,.5);
}
.logo-runs::after{
  content:"";position:absolute;left:-18%;right:-32%;top:47%;height:5px;z-index:-1;
  background:rgba(237,90,66,.9);
  transform:rotate(-4deg);
  box-shadow:0 0 0 2px #0a1425;
}
.subtitle{
  display:flex;align-items:center;gap:12px;margin:2.7vh 0 0;
  font-family:"Bebas",sans-serif;font-size:clamp(20px,2.15vw,33px);letter-spacing:6px;line-height:1;
}
.subtitle span{color:var(--cream)}
.subtitle b{
  color:var(--ink);background:var(--red);padding:5px 11px 3px;
  transform:rotate(-1.4deg);
  box-shadow:4px 4px 0 var(--ink);
  font-weight:400;letter-spacing:5px;
}
.tagline{
  margin:2.1vh 0 2.3vh;max-width:390px;
  font-family:"Barlow",sans-serif;font-weight:600;font-size:clamp(15px,1.18vw,18px);
  line-height:1.42;letter-spacing:.5px;color:rgba(255,243,210,.76);
}
.tagline em{color:var(--gold-hi);font-style:normal}
.menu-actions{display:flex;align-items:stretch;gap:17px}
.start-btn{
  position:relative;
  display:flex;align-items:center;gap:14px;
  padding:12px 14px 12px 18px;
  min-width:290px;
  color:#1b1204;
  background:linear-gradient(180deg,var(--gold-hi) 0%,var(--gold) 44%,#e49a24 100%);
  border:3px solid var(--ink);
  box-shadow:6px 6px 0 rgba(4,10,22,.84),inset 0 1px 0 rgba(255,255,255,.65);
  transform:skew(-2.5deg);
  transition:transform .15s ease,box-shadow .15s ease,filter .15s ease;
}
.start-btn::before{
  content:"";position:absolute;inset:4px;border:1px solid rgba(74,40,2,.23);pointer-events:none;
}
.start-btn:hover{transform:skew(-2.5deg) translate(-2px,-3px);filter:brightness(1.08);box-shadow:9px 9px 0 rgba(4,10,22,.84),0 0 40px rgba(246,184,63,.25)}
.start-btn:active{transform:skew(-2.5deg) translate(3px,3px);box-shadow:2px 2px 0 rgba(4,10,22,.84)}
.start-icon{
  width:32px;height:32px;border-radius:50%;
  border:2px solid rgba(22,13,3,.8);position:relative;flex:0 0 auto;
}
.start-icon::after{
  content:"";position:absolute;left:11px;top:7px;
  border-left:11px solid #1b1204;border-top:7px solid transparent;border-bottom:7px solid transparent;
}
.start-label{display:flex;flex-direction:column;align-items:flex-start;line-height:1;text-align:left}
.start-label small{font-family:"Bebas",sans-serif;font-size:9px;letter-spacing:2.7px;opacity:.67;margin-bottom:4px}
.start-label b{font-family:"Bebas",sans-serif;font-weight:400;font-size:28px;letter-spacing:2.4px}
.start-arrow{margin-left:auto;font-size:28px;font-weight:800;line-height:1;transition:transform .2s}
.start-btn:hover .start-arrow{transform:translateX(5px)}
.best-card{
  display:flex;flex-direction:column;justify-content:center;
  padding:8px 18px;
  min-width:130px;
  border-left:1px solid var(--line);
  font-family:"Bebas",sans-serif;letter-spacing:2.5px;
}
.best-card span{font-size:9px;color:rgba(255,243,210,.5)}
.best-card b{font-weight:400;font-size:27px;color:var(--cream);letter-spacing:2px;margin-top:3px;text-shadow:0 2px 0 #000}
.control-hints{
  display:flex;align-items:flex-end;gap:22px;
  margin-top:3.1vh;
  font-family:"Bebas",sans-serif;
}
.control-hints > div{display:flex;align-items:center;gap:6px}
.control-hints small{font-size:9px;letter-spacing:1.9px;color:rgba(255,243,210,.46);margin-left:3px;line-height:1.1;max-width:60px}
.key{
  display:inline-flex;align-items:center;justify-content:center;
  min-width:24px;height:24px;padding:0 4px;
  border:1px solid rgba(255,243,210,.33);
  background:rgba(255,243,210,.06);
  box-shadow:0 2px 0 rgba(0,0,0,.25);
  font-family:"Barlow",sans-serif;font-weight:800;font-size:12px;color:rgba(255,243,210,.8)
}
.key.wide{min-width:55px;font-family:"Bebas",sans-serif;font-weight:400;font-size:10px;letter-spacing:1.1px}
.swipe-ico{font-size:18px;color:var(--gold);width:26px;text-align:center}
.swipe-hint{display:none!important}

.wanted-card{
  position:absolute;right:4.2vw;top:16.5vh;
  width:clamp(132px,11vw,168px);
  padding:15px 12px 12px;
  color:#2a2418;
  background:
    linear-gradient(145deg,rgba(255,255,255,.18),transparent 35%),
    var(--paper);
  transform:rotate(4.5deg);
  box-shadow:10px 14px 0 rgba(0,0,0,.22),0 22px 40px rgba(0,0,0,.32);
  opacity:.93;
  z-index:3;
  clip-path:polygon(0 1%,14% 0,29% 1.2%,44% 0,60% 1%,76% 0,90% 1.2%,100% 0,100% 100%,88% 99%,72% 100%,55% 98.8%,39% 100%,23% 99%,11% 100%,0 99%);
}
.wanted-card::before{
