torso.castShadow = true;
upper.add(torso);
outline(torso, 1.055);

const chest = new THREE.Mesh(new THREE.SphereGeometry(.23, 12, 8), MAT.cream);
chest.position.set(0, .42, -.20);
chest.scale.set(.9, 1.08, .42);
