  for (const side of [-1, 1]) {
    g.add(box(.11, .42, .12, MAT.iron, side * 1.04, .22, 0));
    g.add(box(.55, .08, .52, MAT.stoneDark, side * 1.04, .035, 0));
  }
  const lamp = sphere(.09, MAT.neonRed, 0, 1.07, 0, 8, 6);
