+}
+function spawnCoin(lane, y, z, value = 10) {
+  let c = coinPool.pop();
+  if (!c) {
+    c = makeCoin();
+    coinGroup.add(c);
+  }
+  c.visible = true;
+  c.position.set(LANES[lane], y, z);
+  c.rotation.y = rnd(0, TAU);
+  c.userData.collected = false;
+  c.userData.baseY = y;
