/* ---------------- COINS & LOOT ---------------- */
const coinGroup = new THREE.Group();
scene.add(coinGroup);
const coins = [];
const coinPool = [];
const coinGeo = new THREE.CylinderGeometry(.31, .31, .075, 14);
const coinMat = new THREE.MeshToonMaterial({ color: 0xffc24b, gradientMap, emissive: 0xb65a06, emissiveIntensity: .65 });
const coinInsetGeo = new THREE.CylinderGeometry(.21, .21, .083, 12);
const coinInsetMat = new THREE.MeshToonMaterial({ color: 0xffe8a1, gradientMap, emissive: 0x9a5005, emissiveIntensity: .45 });

function makeCoin() {
  const g = new THREE.Group();
  const disc = new THREE.Mesh(coinGeo, coinMat);
  disc.rotation.x = Math.PI / 2;
  disc.castShadow = false;
  g.add(disc);
  const inset = new THREE.Mesh(coinInsetGeo, coinInsetMat);
  inset.rotation.x = Math.PI / 2;
  inset.position.z = .001;
  g.add(inset);
  const spark = sprite(glowTex, 1.15, 0xffc95e, .18);
  g.add(spark);
  g.userData = { type: 'coin', collected: false, baseY: 1.1, value: 10 };
  return g;
}
function spawnCoin(lane, y, z, value = 10) {
  let c = coinPool.pop();
  if (!c) {
    c = makeCoin();
    coinGroup.add(c);
  }
  c.visible = true;
  c.position.set(LANES[lane], y, z);
  c.rotation.y = rnd(0, TAU);
  c.userData.collected = false;
  c.userData.baseY = y;
  c.userData.value = value;
  c.userData.z = z;
  coins.push(c);
  return c;
}
function releaseCoin(c) {
  c.visible = false;
  const i = coins.indexOf(c);
  if (i >= 0) coins.splice(i, 1);
  coinPool.push(c);
}

